using System.Net.Http.Headers; using System.Text; using System.Text.Json;
ApplicationConfiguration.Initialize(); Application.Run(new UnbinderForm());
sealed class UnbinderForm:Form { readonly TextBox token=new(){UseSystemPasswordChar=true},code=new(){CharacterCasing=CharacterCasing.Upper};readonly TextBox result=new(){Multiline=true,ReadOnly=true};readonly Button query=new(){Text="查询状态",Height=46},unbind=new(){Text="解除绑定",Height=46};
public UnbinderForm(){Text="wtlyf 卡密解绑器";ClientSize=new(720,500);MinimumSize=new(620,440);BackColor=Color.FromArgb(6,12,27);ForeColor=Color.White;Font=new("Microsoft YaHei UI",11);Padding=new(28);var grid=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=8,ColumnCount=1};grid.Controls.Add(new Label{Text="WTLYF / LICENSE UNBINDER",Font=new("Segoe UI",22,FontStyle.Bold),AutoSize=true,ForeColor=Color.FromArgb(151,120,255)});grid.Controls.Add(new Label{Text="管理员令牌",AutoSize=true,Margin=new(0,28,0,6)});token.Dock=DockStyle.Top;grid.Controls.Add(token);grid.Controls.Add(new Label{Text="卡密",AutoSize=true,Margin=new(0,16,0,6)});code.PlaceholderText="WTLYF-XXXXX-XXXXX-XXXXX-XXXXX";code.Dock=DockStyle.Top;grid.Controls.Add(code);var row=new TableLayoutPanel{Dock=DockStyle.Top,ColumnCount=2,Height=58};query.Dock=DockStyle.Fill;unbind.Dock=DockStyle.Fill;query.BackColor=Color.FromArgb(45,91,155);unbind.BackColor=Color.FromArgb(159,48,90);query.FlatStyle=unbind.FlatStyle=FlatStyle.Flat;row.Controls.Add(query);row.Controls.Add(unbind);grid.Controls.Add(row);result.Dock=DockStyle.Fill;result.BackColor=Color.FromArgb(13,24,47);result.ForeColor=Color.White;grid.Controls.Add(result);Controls.Add(grid);query.Click+=async(_,_)=>await Send("status");unbind.Click+=async(_,_)=>{if(MessageBox.Show("解绑后卡密可被其他设备重新激活，确定继续？","确认解绑",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes)await Send("unbind");};}
async Task Send(string action){query.Enabled=unbind.Enabled=false;result.Text="正在处理…";try{using var client=new HttpClient();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token.Text.Trim());var body=JsonSerializer.Serialize(new{code=code.Text.Trim()});var res=await client.PostAsync("https://wtlyf-license-center.creamy-bowl-8571.chatgpt.site/api/admin/"+action,new StringContent(body,Encoding.UTF8,"application/json"));var text=await res.Content.ReadAsStringAsync();using var json=JsonDocument.Parse(text);if(!res.IsSuccessStatusCode)throw new Exception(json.RootElement.GetProperty("message").GetString());result.Text=json.RootElement.TryGetProperty("license",out var license)?JsonSerializer.Serialize(license,new JsonSerializerOptions{WriteIndented=true}):json.RootElement.GetProperty("message").GetString();}catch(Exception e){result.Text="操作失败："+e.Message;}finally{query.Enabled=unbind.Enabled=true;}}
}

